using System;
using System.Buffers.Binary;
using System.Text;

// 이동/공격 패킷. 와이어 포맷(리틀 엔디언, 패딩 없음):
// [0..4)   Tick      uint32
// [4..6)   EntityId  uint16
// [6..10)  X         float32
// [10..14) Y         float32
// [14..16) SkillId   int16   (-1 = 공격 없음, 이동만)
// [16..18) NameLen   uint16  (Name 의 UTF-8 "바이트" 수, 최대 32)
// [18..)   Name      UTF-8 바이트 NameLen 개 (널 종료 없음)
public struct ActionPacket
{
    public uint Tick;
    public ushort EntityId;
    public float X;
    public float Y;
    public short SkillId;
    public string Name;
}

public static class PacketCodec
{
    public const int FixedSize = 18;
    public const int MaxNameBytes = 32;

    public static bool TryWrite(Span<byte> dst, in ActionPacket p, out int written)
    {
        written = 0;
        ReadOnlySpan<char> name = p.Name;                 // null 이면 빈 span
        int nameBytes = Encoding.UTF8.GetByteCount(name); // 글자 수가 아니라 바이트 수
        if (nameBytes > MaxNameBytes) return false;

        // 쓰기 전에 전체 크기를 한 번에 검사한다: 실패 시 dst 에 반쪽 패킷이 남지 않는다.
        int total = FixedSize + nameBytes;
        if (dst.Length < total) return false;

        BinaryPrimitives.WriteUInt32LittleEndian(dst, p.Tick);
        BinaryPrimitives.WriteUInt16LittleEndian(dst.Slice(4), p.EntityId);
        BinaryPrimitives.WriteSingleLittleEndian(dst.Slice(6), p.X);
        BinaryPrimitives.WriteSingleLittleEndian(dst.Slice(10), p.Y);
        BinaryPrimitives.WriteInt16LittleEndian(dst.Slice(14), p.SkillId);
        BinaryPrimitives.WriteUInt16LittleEndian(dst.Slice(16), (ushort)nameBytes);
        // span 오버로드: 중간 byte[] 를 만들지 않고 dst 에 바로 인코딩한다.
        Encoding.UTF8.GetBytes(name, dst.Slice(FixedSize, nameBytes));

        written = total;
        return true;
    }

    public static bool TryRead(ReadOnlySpan<byte> src, out ActionPacket p, out int consumed)
    {
        p = default;
        consumed = 0;
        if (src.Length < FixedSize) return false;

        // 길이 필드는 상대가 보낸 "주장"일 뿐이다. 상한과 실제 남은 바이트 양쪽으로 검증한다.
        int nameBytes = BinaryPrimitives.ReadUInt16LittleEndian(src.Slice(16));
        if (nameBytes > MaxNameBytes) return false;
        if (src.Length < FixedSize + nameBytes) return false;

        p.Tick = BinaryPrimitives.ReadUInt32LittleEndian(src);
        p.EntityId = BinaryPrimitives.ReadUInt16LittleEndian(src.Slice(4));
        p.X = BinaryPrimitives.ReadSingleLittleEndian(src.Slice(6));
        p.Y = BinaryPrimitives.ReadSingleLittleEndian(src.Slice(10));
        p.SkillId = BinaryPrimitives.ReadInt16LittleEndian(src.Slice(14));
        p.Name = Encoding.UTF8.GetString(src.Slice(FixedSize, nameBytes));

        consumed = FixedSize + nameBytes;
        return true;
    }
}

