using System;
using System.Buffers.Binary;
using System.Collections.Generic;

// 프레임 = [길이 uint16 리틀 엔디언][payload 길이만큼]. payload 는 0 ~ MaxPayload 바이트.
// 연결(소켓) 하나당 MessageFramer 인스턴스 하나를 쓴다.
public sealed class MessageFramer
{
    public const int HeaderSize = 2;
    public const int MaxPayload = 1024;

    private bool _broken;

    // Receive 가 돌려준 바이트 덩어리를 그대로 넘긴다.
    // 완성된 메시지의 payload 를 도착 순서대로 output 에 추가한다.
    // 길이가 MaxPayload 를 넘는 프레임을 만나면 false 를 반환하고, 그 뒤의 Feed 는 항상 false 다.
    public bool Feed(ReadOnlySpan<byte> chunk, List<byte[]> output)
    {
        if (_broken) return false;
        if (chunk.Length < HeaderSize) return true;

        int len = BinaryPrimitives.ReadUInt16LittleEndian(chunk);
        if (len >= MaxPayload)
        {
            _broken = true;
            return false;
        }

        if (chunk.Length < HeaderSize + len) return true;

        output.Add(chunk.Slice(HeaderSize, len).ToArray());
        return true;
    }
}

problems.solutionCode:
using System;
using System.Buffers.Binary;
using System.Collections.Generic;

// 프레임 = [길이 uint16 리틀 엔디언][payload 길이만큼]. payload 는 0 ~ MaxPayload 바이트.
// 연결(소켓) 하나당 MessageFramer 인스턴스 하나를 쓴다.
public sealed class MessageFramer
{
    public const int HeaderSize = 2;
    public const int MaxPayload = 1024;

    // 아직 완성되지 않은 프레임 하나(헤더 + payload)만 보관한다. 크기는 고정이다.
    private readonly byte[] _frame = new byte[HeaderSize + MaxPayload];
    private int _count;      // _frame 에 모인 바이트 수
    private bool _broken;

    public bool Feed(ReadOnlySpan<byte> chunk, List<byte[]> output)
    {
        if (_broken) return false;

        // chunk 를 다 쓸 때까지 돈다: 한 chunk 에 메시지가 0개일 수도, 여러 개일 수도 있다.
        while (chunk.Length > 0)
        {
            // 지금 단계에서 더 필요한 바이트 수: 헤더를 모으는 중인가, payload 를 모으는 중인가
            int need = _count < HeaderSize
                ? HeaderSize - _count
                : HeaderSize + PayloadLength() - _count;

            int take = Math.Min(need, chunk.Length);
            chunk.Slice(0, take).CopyTo(_frame.AsSpan(_count));
            _count += take;
            chunk = chunk.Slice(take);

            if (_count < HeaderSize) break;          // 헤더조차 미완성: 다음 Feed 를 기다린다

            int len = PayloadLength();
            if (len > MaxPayload)                    // payload 를 모으기 전에 헤더만 보고 거절
            {
                _broken = true;
                return false;
            }

            if (_count == HeaderSize + len)          // 프레임 완성 (len == 0 포함)
            {
                output.Add(_frame.AsSpan(HeaderSize, len).ToArray());
                _count = 0;
            }
        }
        return true;
    }

    private int PayloadLength() => BinaryPrimitives.ReadUInt16LittleEndian(_frame);
}

