problems.solutionCode:
using System;

// 원격 플레이어 한 명의 위치 스냅샷 버퍼. 시간 단위는 서버 시각(ms, 정수).
public sealed class SnapshotBuffer
{
    // 고정 크기 링 버퍼. _head 가 가장 오래된 스냅샷, 논리 인덱스 k 는 (_head + k) % capacity.
    private readonly long[] _time;
    private readonly float[] _x;
    private readonly float[] _y;
    private int _head;
    private int _count;

    public SnapshotBuffer(int capacity)
    {
        if (capacity < 2) throw new ArgumentOutOfRangeException(nameof(capacity));
        _time = new long[capacity];
        _x = new float[capacity];
        _y = new float[capacity];
    }

    public int Count => _count;

    private int Slot(int k) => (_head + k) % _time.Length;

    public bool Add(long timeMs, float x, float y)
    {
        // 시간이 엄격히 증가할 때만 받는다: 버퍼는 항상 시간순으로 정렬된 상태가 된다.
        if (_count > 0 && timeMs <= _time[Slot(_count - 1)]) return false;

        if (_count == _time.Length)
        {
            _head = (_head + 1) % _time.Length;   // 가장 오래된 것을 덮어쓴다 (배열을 밀지 않는다)
            _count--;
        }

        int i = Slot(_count);
        _time[i] = timeMs;
        _x[i] = x;
        _y[i] = y;
        _count++;
        return true;
    }

    public bool TrySample(long renderTimeMs, out float x, out float y)
    {
        x = 0f;
        y = 0f;
        if (_count == 0) return false;

        int newest = Slot(_count - 1);
        if (renderTimeMs >= _time[newest]) { x = _x[newest]; y = _y[newest]; return true; }
        if (renderTimeMs <= _time[_head]) { x = _x[_head]; y = _y[_head]; return true; }

        // 여기서는 oldest < renderTime < newest 이므로 _count >= 2 이고 감싸는 구간이 반드시 있다.
        // 렌더 시각은 보통 최신 쪽에 가까우므로 최신에서 과거로 훑는다.
        for (int k = _count - 2; k >= 0; k--)
        {
            int a = Slot(k);
            if (_time[a] > renderTimeMs) continue;
            int b = Slot(k + 1);
            // long 끼리 먼저 빼고 나서 float 로 바꾼다. 큰 타임스탬프를 float 로 바꾼 뒤 빼면 정밀도가 사라진다.
            float t = (float)(renderTimeMs - _time[a]) / (float)(_time[b] - _time[a]);
            x = _x[a] + (_x[b] - _x[a]) * t;
            y = _y[a] + (_y[b] - _y[a]) * t;
            return true;
        }

        x = _x[_head];
        y = _y[_head];
        return true;
    }
}

