using System;

// 비트 스트림 규약 (LSB 우선)
//  - 스트림의 k번째 비트(0부터)는 buffer[k / 8] 의 비트 (k % 8) 에 놓인다. 비트 0 은 0x01 자리다.
//  - 값은 최하위 비트부터 기록한다.
//  예) TryWriteBits(0b101, 3) 다음 TryWriteBits(0b11, 2)  ->  buffer[0] == 0b0001_1101 (0x1D)

public sealed class BitWriter
{
    private readonly byte[] _buffer;
    private int _bitPos;

    public BitWriter(byte[] buffer)
    {
        _buffer = buffer ?? throw new ArgumentNullException(nameof(buffer));
    }

    public int BitsWritten => _bitPos;
    public int BytesWritten => (_bitPos + 7) / 8;

    public bool TryWriteBits(uint value, int bits)
    {
        if (bits < 1 || bits > 32) throw new ArgumentOutOfRangeException(nameof(bits));
        // bits == 32 일 때 value >> 32 는 value >> 0 이 된다(uint 의 시프트 수는 하위 5비트만 쓰인다). 그래서 따로 건너뛴다.
        if (bits < 32 && (value >> bits) != 0) throw new ArgumentOutOfRangeException(nameof(value));

        // 쓰기 전에 공간을 먼저 확인한다: 실패하면 버퍼도 위치도 그대로여야 한다.
        if (bits > _buffer.Length * 8L - _bitPos) return false;

        int remaining = bits;
        while (remaining > 0)
        {
            int byteIndex = _bitPos >> 3;
            int offset = _bitPos & 7;                       // 이 바이트에서 이미 찬 비트 수
            int take = Math.Min(8 - offset, remaining);     // 이번에 이 바이트에 넣을 비트 수 (1 ~ 8)
            uint chunk = value & ((1u << take) - 1u);       // take <= 8 이므로 마스크 계산이 안전하다

            if (offset == 0) _buffer[byteIndex] = 0;        // 새 바이트를 시작할 때 이전 내용(재사용 버퍼)을 지운다
            _buffer[byteIndex] |= (byte)(chunk << offset);

            value >>= take;                                 // take <= 8
            remaining -= take;
            _bitPos += take;
        }
        return true;
    }
}

public sealed class BitReader
{
    private readonly byte[] _buffer;
    private readonly int _bitLength;
    private int _bitPos;

    public BitReader(byte[] buffer, int byteLength)
    {
        _buffer = buffer ?? throw new ArgumentNullException(nameof(buffer));
        if (byteLength < 0 || byteLength > buffer.Length) throw new ArgumentOutOfRangeException(nameof(byteLength));
        _bitLength = byteLength * 8;
    }

    public int BitsRead => _bitPos;

    public bool TryReadBits(int bits, out uint value)
    {
        if (bits < 1 || bits > 32) throw new ArgumentOutOfRangeException(nameof(bits));

        value = 0;
        // 패킷 길이(byteLength) 기준으로 검사한다. buffer.Length 가 아니다.
        if (bits > _bitLength - _bitPos) return false;

        int got = 0;
        while (got < bits)
        {
            int byteIndex = _bitPos >> 3;
            int offset = _bitPos & 7;
            int take = Math.Min(8 - offset, bits - got);
            uint chunk = ((uint)_buffer[byteIndex] >> offset) & ((1u << take) - 1u);

            value |= chunk << got;                          // got <= 31
            got += take;
            _bitPos += take;
        }
        return true;
    }
}

