                        if (no > latest) latest = no;
                        if (latest - no <= 32) got.Add(no);
                    }
                    if (latest < 0) continue;
                    uint bits = 0;
                    for (int n = 1; n <= 32; n++) if (got.Contains(latest - n)) bits |= 1u << (n - 1);
                    if (recv.Ack != (ushort)(latest & 0xFFFF) || recv.AckBits != bits)
