        {
            var p = new PredictedPlayer(0f);
            for (int i = 0; i < 4; i++) p.ApplyInput(1, 0.125f);                         // 4
            p.OnServerState(3, 3f);
            p.OnServerState(2, 0f);                                                       // 늦게 온 옛 상태
            string e = Chk(p, 4f, 4f, 1, "상태 (Seq 3) 뒤에 도착한 옛 상태 (Seq 2, X 0)");
            if (e != null) return e;
            p.OnServerState(3, 3.5f);                                                     // 같은 번호, 새 위치: 받아들인다
            return Chk(p, 4.5f, 4f, 1, "같은 번호의 새 상태 (Seq 3, X 3.5)");
        });

        Run("random-vs-reference", () =>
        {
            _lcg = 99u;
            for (int run = 0; run < 30; run++)
            {
                var p = new PredictedPlayer(0f);
                var pend = new System.Collections.Generic.List<InputCmd>();   // 기준: 미확인 입력
                var wire = new System.Collections.Generic.List<InputCmd>();   // 서버로 가는 중인 입력
                float server = 0f, sim = 0f, off = 0f; uint acked = 0; int dir = 1;
                for (int f = 0; f < 400; f++)
                {
                    if (Next(8) == 0) dir = (int)Next(3) - 1;
                    float dt = (1 + Next(4)) / 64f;
                    InputCmd c = p.ApplyInput(dir, dt);
                    pend.Add(c); wire.Add(c); sim = MoveSim.Step(sim, dir, dt);
                    if (wire.Count > 2 + (run % 6) && Next(3) != 0)
                    {
                        int n = 1 + (int)Next(2);
                        for (int k = 0; k < n && wire.Count > 0; k++) { server = MoveSim.Step(server, wire[0].Dir, wire[0].Dt); acked = wire[0].Seq; wire.RemoveAt(0); }
                        uint kind = Next(12);
                        if (kind == 0) server += ((int)Next(9) - 4) * 0.25f;          // 작은 밀림
                        else if (kind == 1) server += ((int)Next(2) * 2 - 1) * 6f;    // 큰 순간이동
                        float before = sim + off;
                        pend.RemoveAll(i => i.Seq <= acked);
                        sim = server;
                        foreach (var i in pend) sim = MoveSim.Step(sim, i.Dir, i.Dt);
                        float err = before - sim;
                        off = System.Math.Abs(err) > PredictedPlayer.SnapDistance ? 0f : err;
                        p.OnServerState(acked, server);
                    }
                    p.UpdateVisual();
                    off *= PredictedPlayer.SmoothFactor; if (System.Math.Abs(off) < PredictedPlayer.MinOffset) off = 0f;
                    if (!Near(p.SimX, sim) || !Near(p.RenderX, sim + off) || p.PendingCount != pend.Count)
                        return run + "회차 " + f + "프레임: 기대 SimX " + sim + ", RenderX " + (sim + off) + ", 대기 " + pend.Count + " / 결과 SimX " + p.SimX + ", RenderX " + p.RenderX + ", 대기 " + p.PendingCount;
                }
            }
            return null;
        });
    }
}

