using System;
using System.Collections.Generic;

public struct MoveInput
{
    public uint Seq;   // 클라이언트가 붙이는 입력 번호. 1 부터 1씩 증가
    public int Dir;    // -1(왼쪽), 0(정지), +1(오른쪽)
}

public struct ServerState
{
    public uint LastProcessedSeq;   // 서버가 마지막으로 처리한 입력 번호. 아직 없으면 0
    public int X;                   // 그 입력까지 처리한 뒤의 위치(cm)
}

// 클라이언트와 서버가 똑같이 쓰는 이동 규칙: 한 틱에 10cm, 복도 [0, 1000] 밖으로 못 나간다.
public static class Movement
{
    public const int MinX = 0, MaxX = 1000, StepPerTick = 10;
    public static int Step(int x, int dir) => Math.Clamp(x + dir * StepPerTick, MinX, MaxX);
}

// (참고용) 지연이 있는 링크. 보낸 지 delayTicks 틱이 지난 메시지를 보낸 순서대로 꺼낼 수 있다(유실·순서 뒤바뀜 없음).
// 이 문제를 푸는 데 내부를 읽을 필요는 없다.
public sealed class DelayedLink<T>
{
