    public DelayedLink(int delayTicks) { _delayTicks = delayTicks; }

    public void Send(T msg, int nowTick) => _queue.Enqueue((nowTick + _delayTicks, msg));

    public bool TryReceive(int nowTick, out T msg)
    {
        if (_queue.Count > 0 && _queue.Peek().due <= nowTick) { msg = _queue.Dequeue().msg; return true; }
        msg = default(T);
        return false;
    }
}

// (참고용) 권위 서버. 매 틱 도착한 입력을 모두 적용하고 현재 상태를 보낸다.
// 이 문제를 푸는 데 내부를 읽을 필요는 없다.
public sealed class AuthoritativeServer
{
    private readonly DelayedLink<MoveInput> _fromClient;
    private readonly DelayedLink<ServerState> _toClient;
    private uint _lastProcessedSeq;

    public int X { get; private set; }

    public AuthoritativeServer(int startX, DelayedLink<MoveInput> fromClient, DelayedLink<ServerState> toClient)
    {
        X = startX; _fromClient = fromClient; _toClient = toClient;
    }

    // 넉백처럼 클라이언트가 예측할 수 없는 서버 쪽 변화.
    public void Push(int dx) { X = Math.Clamp(X + dx, Movement.MinX, Movement.MaxX); }

    public void Tick(int nowTick)
    {
        while (_fromClient.TryReceive(nowTick, out MoveInput input))
        {
            X = Movement.Step(X, input.Dir);
            _lastProcessedSeq = input.Seq;
        }
        _toClient.Send(new ServerState { LastProcessedSeq = _lastProcessedSeq, X = X }, nowTick);
    }
}

// 내 캐릭터를 조종하는 클라이언트. 입력을 서버 응답을 기다리지 않고 바로 반영(예측)하고,
// 서버 상태가 오면 그 상태에서 다시 계산(재조정)한다.
public sealed class PredictedClient
{
    private readonly DelayedLink<MoveInput> _toServer;
    private readonly DelayedLink<ServerState> _fromServer;

    // 보냈지만 서버가 아직 처리했다고 알려 주지 않은 입력. 번호 오름차순으로 쌓인다.
    private readonly List<MoveInput> _pending = new List<MoveInput>();
    private uint _nextSeq = 1;

    public PredictedClient(int startX, DelayedLink<MoveInput> toServer, DelayedLink<ServerState> fromServer)
    {
        X = startX;
        _toServer = toServer;
        _fromServer = fromServer;
    }

    // 화면에 그릴 내 캐릭터의 예측 위치.
    public int X { get; private set; }

    // 보냈지만 서버가 아직 처리했다고 알려 주지 않은 입력의 수.
    public int PendingCount => _pending.Count;

    // 매 틱 한 번 호출된다. dir 은 이번 틱의 입력(-1, 0, +1). 이미 구현되어 있다.
    public void Tick(int nowTick, int dir)
    {
        // 1) 도착해 있는 서버 상태를 모두, 도착한 순서대로 재조정에 넘긴다(한 틱에 여러 개가 올 수 있다).
        while (_fromServer.TryReceive(nowTick, out ServerState state))
            Reconcile(state);

        // 2) 예측: 이번 입력에 번호를 붙여 바로 X 에 반영하고, 보관하고, 서버로 보낸다(dir 이 0 이어도 보낸다).
        var input = new MoveInput { Seq = _nextSeq++, Dir = dir };
        X = Movement.Step(X, input.Dir);
        _pending.Add(input);
        _toServer.Send(input, nowTick);
    }

    // 서버 상태 하나를 반영한다(재조정).
    private void Reconcile(ServerState state)
    {
        // 서버가 이미 처리한 입력(LastProcessedSeq 번 포함)은 서버 위치에 반영되어 있다. 보관본에서 버린다.
        int acked = 0;
        while (acked < _pending.Count && _pending[acked].Seq <= state.LastProcessedSeq) acked++;
        _pending.RemoveRange(0, acked);

        // 서버 위치(과거)에서 출발해, 서버가 아직 못 본 입력을 순서대로 다시 적용하면 '현재'가 된다.
        int x = state.X;
        for (int i = 0; i < _pending.Count; i++)
            x = Movement.Step(x, _pending[i].Dir);
        X = x;
    }
}

