public static class __Judge
{
    static void Run(string id, System.Func<string> body)
    {
        string err;
        try { err = body(); }
        catch (System.Exception e) { err = "예외 발생: " + e.GetType().Name; }
        System.Console.WriteLine(err == null ? "[PASS] " + id : "[FAIL] " + id + " :: " + err);
    }

    static uint _lcg;
    static uint Next(uint mod) { _lcg = unchecked(_lcg * 1664525u + 1013904223u); return (_lcg >> 8) % mod; }

    static ServerState St(uint seq, int x) { return new ServerState { LastProcessedSeq = seq, X = x }; }

    // 서버 없이 클라이언트만 세운다. down 은 지연 0 이라 Send 한 상태가 다음 Tick 에서 바로 읽힌다.
    static PredictedClient Solo(int startX, out DelayedLink<MoveInput> up, out DelayedLink<ServerState> down)
    {
        up = new DelayedLink<MoveInput>(0);
        down = new DelayedLink<ServerState>(0);
        return new PredictedClient(startX, up, down);
    }

    static string Expect(PredictedClient c, int x, int pending, string when)
    {
        if (c.X != x) return when + ": X 기대 " + x + " / 결과 " + c.X;
        if (c.PendingCount != pending) return when + ": PendingCount 기대 " + pending + " / 결과 " + c.PendingCount;
        return null;
    }

    // 채점용 기준 클라이언트(단순 구현)
    sealed class Ref
    {
        public int X; public System.Collections.Generic.List<MoveInput> P = new System.Collections.Generic.List<MoveInput>(); uint _n = 1;
        DelayedLink<MoveInput> _up; DelayedLink<ServerState> _down;
        public Ref(int x, DelayedLink<MoveInput> up, DelayedLink<ServerState> down) { X = x; _up = up; _down = down; }
        public void Tick(int now, int dir)
        {
            ServerState s;
            while (_down.TryReceive(now, out s))
            {
                P.RemoveAll(i => i.Seq <= s.LastProcessedSeq);
                X = s.X;
                foreach (var i in P) X = Movement.Step(X, i.Dir);
            }
            var inp = new MoveInput { Seq = _n++, Dir = dir };
            X = Movement.Step(X, dir); P.Add(inp); _up.Send(inp, now);
        }
    }

    public static void Main()
    {
        Run("input-applies-immediately", () =>
        {
            DelayedLink<MoveInput> up; DelayedLink<ServerState> down;
            var c = Solo(500, out up, out down);
            if (c.X != 500) return "시작 위치 기대 500 / 결과 " + c.X;
