problems.solutionCode:
using System;

// 틱 레이트·전송률·보간 지연 사이의 관계를 계산하는 도우미.
public static class NetTiming
{
    // 스냅샷 전송 간격(ms) = 1000 / 초당 전송 횟수.
    public static double SendIntervalMs(int sendRateHz)
    {
        // 1000 / sendRateHz 로 쓰면 int 끼리의 나눗셈이 되어 소수부가 버려진다.
        if (sendRateHz <= 0) throw new ArgumentOutOfRangeException(nameof(sendRateHz));
        return 1000.0 / sendRateHz;
    }

    // 서버가 시뮬레이션 틱 몇 번마다 스냅샷을 한 번 보내는가.
    // 틱 사이에는 보낼 새 상태가 없으므로 tickRateHz 는 sendRateHz 의 배수여야 한다.
    public static int TicksPerSend(int tickRateHz, int sendRateHz)
    {
        if (tickRateHz <= 0) throw new ArgumentOutOfRangeException(nameof(tickRateHz));
        if (sendRateHz <= 0) throw new ArgumentOutOfRangeException(nameof(sendRateHz));
        if (tickRateHz % sendRateHz != 0)
            throw new ArgumentException("tickRateHz 는 sendRateHz 의 배수여야 합니다.");
        return tickRateHz / sendRateHz;
    }

    // 보간 지연(ms) = (연속 유실 허용 개수 + 1) × 전송 간격 + 지터 여유.
    public static double InterpolationDelayMs(int sendRateHz, int toleratedConsecutiveLosses, double jitterMarginMs)
    {
        if (sendRateHz <= 0) throw new ArgumentOutOfRangeException(nameof(sendRateHz));
        if (toleratedConsecutiveLosses < 0) throw new ArgumentOutOfRangeException(nameof(toleratedConsecutiveLosses));
        if (double.IsNaN(jitterMarginMs) || jitterMarginMs < 0) throw new ArgumentOutOfRangeException(nameof(jitterMarginMs));

        // 1000.0 으로 시작해 double 나눗셈이 되게 한다.
        return (toleratedConsecutiveLosses + 1) * 1000.0 / sendRateHz + jitterMarginMs;
    }
}

