{{USER_CODE}}

public static class __Judge
{
    static void Run(string id, System.Func<string> body)
    {
        string err;
        try { err = body(); }
        catch (System.Exception e) { err = "예외 발생: " + e.GetType().Name; }
        System.Console.WriteLine(err == null ? "[PASS] " + id : "[FAIL] " + id + " :: " + err);
    }

    // Poll 한 번의 결과를 "F3:30"(3번 프레임, 내용 30) / "M3"(3번 없음) / "-"(없음) 로 만든다
    static string Ev(JitterBuffer b, long now)
    {
        int f, p;
        PollResult r = b.Poll(now, out f, out p);
        return r == PollResult.Frame ? "F" + f + ":" + p : (r == PollResult.Missing ? "M" + f : "-");
    }

    static string Want(JitterBuffer b, long now, string want)
    {
        string got = Ev(b, now);
        return got == want ? null : "Poll(" + now + ") 기대 " + want + " / 결과 " + got;
    }

    static string Push(JitterBuffer b, int frame, long now, bool want)
    {
        bool got = b.Push(frame, now, frame * 10);
        return got == want ? null : "Push(frame " + frame + ", " + now + "ms) 기대 " + want + " / 결과 " + got;
    }

    // 채점용 기준 구현(사전 기반의 단순 구현)
    sealed class Ref
    {
        int _iv, _min, _max, _next, _j16; bool _started; long _play, _prev;
        System.Collections.Generic.Dictionary<int, int> _buf = new System.Collections.Generic.Dictionary<int, int>();
        public int Cur, Late;
        public Ref(int iv, int min, int max) { _iv = iv; _min = min; _max = max; Cur = min; }
        public int Jit { get { return _j16 >> 4; } }
        public int Target { get { return System.Math.Min(_max, System.Math.Max(_min, 3 * Jit)); } }
        void Obs(int f, long now) { long tr = now - (long)f * _iv; long d = System.Math.Abs(tr - _prev); _prev = tr; _j16 += (int)d - ((_j16 + 8) >> 4); }
        public bool Push(int f, long now, int p)
        {
            if (!_started) { _started = true; _next = f; _play = now + Cur; _prev = now - (long)f * _iv; _buf[f] = p; return true; }
            if (f < _next) { Late++; Obs(f, now); return false; }
            if (f >= _next + 64 || _buf.ContainsKey(f)) return false;
            Obs(f, now); _buf[f] = p; return true;
        }
        public string Poll(long now)
        {
            if (!_started || now < _play) return "-";
            int f = _next++; string r;
            if (_buf.ContainsKey(f)) { r = "F" + f + ":" + _buf[f]; _buf.Remove(f); } else r = "M" + f;
            int step = System.Math.Min(2, System.Math.Max(-2, Target - Cur));
            Cur += step; _play += _iv + step;
            return r;
        }
    }

    static uint _lcg;
    static uint Next(uint mod) { _lcg = unchecked(_lcg * 1664525u + 1013904223u); return (_lcg >> 8) % mod; }

    public static void Main()
    {
        Run("steady-cadence", () =>
        {
            var b = new JitterBuffer(20, 40, 120);
            string e = Want(b, 500, "-");                                  // 아무것도 받기 전
            if (e != null) return e;
            for (int f = 0; f < 6; f++) { e = Push(b, f, 1000 + 20 * f, true) ?? (f == 0 ? Want(b, 1039, "-") : null); if (e != null) return e; }
            e = Want(b, 1040, "F0:0") ?? Want(b, 1040, "-") ?? Want(b, 1059, "-") ?? Want(b, 1060, "F1:10") ?? Want(b, 1080, "F2:20")
                ?? Want(b, 1099, "-") ?? Want(b, 1100, "F3:30") ?? Want(b, 1120, "F4:40") ?? Want(b, 1140, "F5:50");
            if (e != null) return e;
            if (b.CurrentDelayMs != 40 || b.JitterMs != 0 || b.LateCount != 0) return "지터가 없는 흐름: CurrentDelayMs 40, JitterMs 0, LateCount 0 기대 / 결과 " + b.CurrentDelayMs + ", " + b.JitterMs + ", " + b.LateCount;
            return null;
        });

