        Run("jitter-estimate-rfc3550", () =>
        {
            var b = new JitterBuffer(20, 10, 200);
            int[] off = { 0, 12, 0, 12, 0, 30, 5, 0, 20, 0 };
            int[] wantJ = { 0, 0, 1, 2, 2, 4, 5, 5, 6, 7 };
            for (int f = 0; f < off.Length; f++)
            {
                b.Push(f, 5000 + 20 * f + off[f], f);
                if (b.JitterMs != wantJ[f]) return f + "번 패킷(도착 지연 " + off[f] + "ms)까지 반영한 JitterMs 기대 " + wantJ[f] + " / 결과 " + b.JitterMs;
                int wantT = System.Math.Max(10, 3 * wantJ[f]);
                if (b.TargetDelayMs != wantT) return f + "번 패킷 뒤 TargetDelayMs 기대 " + wantT + " / 결과 " + b.TargetDelayMs;
            }
            var c = new JitterBuffer(20, 10, 200);
            for (int f = 0; f < 40; f++) c.Push(f, 100 + 20 * f + (f % 2) * 300, f);
            if (c.TargetDelayMs != 200) return "지터가 아주 큰 흐름: TargetDelayMs 는 maxDelayMs(200) 로 잘려야 함 / 결과 " + c.TargetDelayMs;
            if (c.CurrentDelayMs != 10) return "아직 프레임을 하나도 내보내지 않았으므로 CurrentDelayMs 는 처음 값 10 / 결과 " + c.CurrentDelayMs;
            return null;
        });

        Run("delay-adapts-in-small-steps", () =>
        {
            var b = new JitterBuffer(20, 40, 120);
            // 0 ~ 199번: 홀수 프레임만 60ms 늦게 도착(지터 큼). 200 ~ 699번: 제때 도착(지터 없음).
            long lastEvent = -1; int prevDelay = 40, events = 0, delayAt199 = -1, lateMissing = 0;
            for (long t = 1000; t <= 1000 + 20 * 700 + 200; t++)
            {
                long k = t - 1000;
                if (k % 20 == 0 && k / 20 < 700 && ((k / 20) % 2 == 0 || k / 20 >= 200)) b.Push((int)(k / 20), t, 1);
                long k2 = k - 60;
                if (k2 >= 0 && k2 % 20 == 0 && k2 / 20 < 200 && (k2 / 20) % 2 == 1) b.Push((int)(k2 / 20), t, 1);
                int f, p; PollResult r;
                while ((r = b.Poll(t, out f, out p)) != PollResult.None)
                {
                    events++;
                    if (lastEvent >= 0 && (t - lastEvent < 18 || t - lastEvent > 22)) return f + "번 프레임: 직전 방출과의 간격 " + (t - lastEvent) + "ms (20 ± 2 여야 함)";
                    lastEvent = t;
                    int d = b.CurrentDelayMs;
                    if (d < 40 || d > 120) return f + "번 프레임 뒤 CurrentDelayMs " + d + " (40 ~ 120 이어야 함)";
                    if (System.Math.Abs(d - prevDelay) > 2) return f + "번 프레임 뒤 CurrentDelayMs 가 한 번에 " + prevDelay + " → " + d + " 로 바뀜(최대 2ms)";
                    prevDelay = d;
                    if (f == 199) delayAt199 = d;
                    if (f >= 150 && f < 200 && r == PollResult.Missing) lateMissing++;
                }
            }
            if (delayAt199 != 120) return "지터가 큰 구간의 끝(199번 프레임)에서 CurrentDelayMs 기대 120 / 결과 " + delayAt199;
            if (lateMissing != 0) return "지연이 충분히 늘어난 뒤(150 ~ 199번)에도 Missing 이 " + lateMissing + "번 나옴";
            if (b.CurrentDelayMs != 40 || b.JitterMs != 0) return "지터가 사라진 뒤 CurrentDelayMs 40, JitterMs 0 기대 / 결과 " + b.CurrentDelayMs + ", " + b.JitterMs;
            if (events < 700) return "방출 이벤트 수 " + events + " (700 이상이어야 함)";
            return null;
        });

