        Run("random-trace-vs-reference", () =>
        {
            _lcg = 3550u;
            for (int run = 0; run < 25; run++)
            {
                int iv = new[] { 10, 20, 33 }[run % 3], min = 10 + (int)Next(40), max = min + 20 + (int)Next(150);
                var b = new JitterBuffer(iv, min, max); var r = new Ref(iv, min, max);
                var arr = new System.Collections.Generic.List<long[]>();           // { 도착 시각, 프레임, 생성 순서 }
                int first = (int)Next(500);
                for (int f = 0; f < 400; f++)
                {
                    int amp = (f / 80) % 3 == 0 ? 6 : ((f / 80) % 3 == 1 ? 45 : 160);
                    long at = 2000 + (long)f * iv + Next((uint)amp);
                    if (Next(10) != 0) arr.Add(new long[] { at, first + f, arr.Count });
                    if (Next(10) == 0) arr.Add(new long[] { at + Next(60), first + f, arr.Count });      // 중복
                    if (Next(60) == 0) arr.Add(new long[] { at, first + f + 64 + Next(40), arr.Count });   // 창 밖
                }
                arr.Sort((x, y) => x[0] != y[0] ? x[0].CompareTo(y[0]) : x[2].CompareTo(y[2]));
                int ai = 0; long end = arr[arr.Count - 1][0] + 300;
                for (long t = 2000; t <= end; t++)
                {
                    while (ai < arr.Count && arr[ai][0] == t)
                    {
                        int f = (int)arr[ai][1]; ai++;
                        bool want = r.Push(f, t, f * 3), got = b.Push(f, t, f * 3);
                        if (want != got) return run + "회차 " + t + "ms: Push(frame " + f + ") 기대 " + want + " / 결과 " + got;
                    }
                    if (Next(3) == 0)
                    {
                        while (true)
                        {
                            string want = r.Poll(t), got = Ev(b, t);
                            if (want != got) return run + "회차 " + t + "ms: Poll 기대 " + want + " / 결과 " + got;
                            if (want == "-") break;
                        }
                    }
                    if (b.JitterMs != r.Jit || b.TargetDelayMs != r.Target || b.CurrentDelayMs != r.Cur || b.LateCount != r.Late)
                        return run + "회차 " + t + "ms: 기대 JitterMs " + r.Jit + ", TargetDelayMs " + r.Target + ", CurrentDelayMs " + r.Cur + ", LateCount " + r.Late
                            + " / 결과 " + b.JitterMs + ", " + b.TargetDelayMs + ", " + b.CurrentDelayMs + ", " + b.LateCount;
                }
            }
            return null;
        });
